import '../../theme/theme_center_complete_panel.dart';
import '../../workspace/portal_workspace.dart';
import 'package:primecare_ui_foundation/primecare_ui_foundation.dart' show PrimeDrawer, PrimeSwitchListTile;
import 'package:flutter_core/theme/theme_contrast.dart';
import 'package:primecare_ui_foundation/primecare_ui_foundation.dart' show PrimeCard;
import 'package:primecare_ui_foundation/primecare_ui_foundation.dart' show PrimeIconButton;
import 'package:primecare_ui_foundation/primecare_ui_foundation.dart' show PrimeOutlinedButton;
import 'theme_center_panel.dart';
import '../../theme/theme_center_catalog_generated.dart';
import 'package:primecare_ui_foundation/primecare_ui_foundation.dart' show PrimeText;
import 'package:primecare_ui_foundation/primecare_ui_foundation.dart' show PrimeIcon;

import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:lucide_icons_flutter/lucide_icons.dart';
import 'package:easy_localization/easy_localization.dart' hide TextDirection;
import '../../theme/theme_config_generated.dart';
import '../../theme/theme_settings_provider.dart';
import '../../src/localization/language_provider.dart';
import '../../providers/platform_providers.dart';

const ThemeSettingsDrawer({
  super.key,
  required this.tenantDefaultPreset,
});

@override
Widget build(BuildContext context, WidgetRef ref) {
  final settings = ref.watch(themeSettingsProvider);
  final notifier = ref.read(themeSettingsProvider.notifier);

  final presetsList = themeCenterPresetNames;

  return PrimeDrawer(
    child: SafeArea(
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          // Drawer Header
          Padding(
            padding: const EdgeInsets.all(16.0),
            child: Row(
              children: [
                const PrimeIcon(LucideIcons.settings, size: 24),
                const SizedBox(width: 12),
                Expanded(child: PrimeText(
                  themeCenterText(context,'theme_center'),
                  style: Theme.of(context).textTheme.titleMedium?.copyWith(
                        fontWeight: FontWeight.bold,
                      ),
                )),
                PrimeIconButton(
                  icon: const PrimeIcon(LucideIcons.x, size: 20),
                  onPressed: () => Navigator.of(context).pop(),
                ),
              ],
            ),
          ),
          const Divider(),

          // Content Scroll
          Expanded(
            child: ListView(
              padding: const EdgeInsets.all(16.0),
              children: [
                const ThemeCenterCompletePanel(),
                const ThemeCenterPanel(),
                if (PortalWorkspaceScope.maybeOf(context) != null) const PortalLayoutEditor(),
                if (PortalWorkspaceScope.maybeOf(context) == null) ...[
                // Section: Layout Styles
                PrimeText(
                  'LAYOUT STYLE',
                  style: Theme.of(context).textTheme.labelSmall?.copyWith(
                        fontWeight: FontWeight.bold,
                        letterSpacing: 1.2,
                        color: Theme.of(context).colorScheme.onSurfaceVariant,
                      ),
                ),
                const SizedBox(height: 12),
                _LayoutOptionCard(
                  title: 'Vertical Left',
                  subtitle: 'Sidebar on the left',
                  icon: LucideIcons.alignLeft,
                  isSelected: settings.layoutStyle == LayoutStyle.verticalLeft,
                  onTap: () => notifier.updateLayoutStyle(LayoutStyle.verticalLeft),
                ),
                _LayoutOptionCard(
                  title: 'Vertical Right',
                  subtitle: 'Sidebar on the right',
                  icon: LucideIcons.alignRight,
                  isSelected: settings.layoutStyle == LayoutStyle.verticalRight,
                  onTap: () => notifier.updateLayoutStyle(LayoutStyle.verticalRight),
                ),
                _LayoutOptionCard(
                  title: 'Horizontal Navigation',
                  subtitle: 'Navbar on the top',
                  icon: LucideIcons.menu,
                  isSelected: settings.layoutStyle == LayoutStyle.horizontal,
                  onTap: () => notifier.updateLayoutStyle(LayoutStyle.horizontal),
                ),
                _LayoutOptionCard(
                  title: 'Collapsed Navigation',
                  subtitle: 'Mini sidebar icons',
                  icon: LucideIcons.columns,
                  isSelected: settings.layoutStyle == LayoutStyle.collapsed,
                  onTap: () => notifier.updateLayoutStyle(LayoutStyle.collapsed),
                ),
                const SizedBox(height: 24),

                ],
                // Section: Preset Colors
                PrimeText(
                  'THEME PRESETS',
                  style: Theme.of(context).textTheme.labelSmall?.copyWith(
                        fontWeight: FontWeight.bold,
                        letterSpacing: 1.2,
                        color: Theme.of(context).colorScheme.onSurfaceVariant,
                      ),
                ),
                const SizedBox(height: 12),
                GridView.builder(
                  shrinkWrap: true,
                  physics: const NeverScrollableScrollPhysics(),
                  gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(
                    crossAxisCount: 4,
                    crossAxisSpacing: 10,
                    mainAxisSpacing: 10,
                    childAspectRatio: 1,
                  ),
                  itemCount: presetsList.length,
                  itemBuilder: (context, index) {
                    final name = presetsList[index];
                    final palette = ThemeConfig.getAppPalette(name);
                    final isSelected = settings.presetName == name;

                    return Tooltip(
                      message: name,
                      child: InkWell(
                        onTap: () => notifier.updatePreset(name),
                        borderRadius: BorderRadius.circular(20),
                        child: Container(
                          decoration: BoxDecoration(
                            shape: BoxShape.circle,
                            color: palette.primary,
                            border: Border.all(
                              color: isSelected
                                  ? readableThemeForeground(palette.primary, palette.textPrimary)
                                  : Theme.of(context).colorScheme.surface.withValues(alpha: 0),
                              width: 3,
                            ),
                            boxShadow: [
                              BoxShadow(
                                color: palette.primary.withValues(alpha: 0.3),
                                blurRadius: 4,
                                offset: const Offset(0, 2),
                              ),
                            ],
                          ),
                          child: isSelected
                              ? PrimeIcon(
                                  LucideIcons.check,
                                  size: 16,
                                  color: palette.onPrimary,
                                )
                              : null,
                        ),
                      ),
                    );
                  },
                ),
                const SizedBox(height: 24),

                // Section: Options & Switches
                PrimeText(
                  'APPLICATION LANGUAGE',
                  style: Theme.of(context).textTheme.labelSmall?.copyWith(
                        fontWeight: FontWeight.bold,
                        letterSpacing: 1.2,
                        color: Theme.of(context).colorScheme.onSurfaceVariant,
                      ),
                ),
                const SizedBox(height: 12),
                ...() {
                  String activeLang = ref.watch(languageProvider);
                  List<String> supportedLanguages = const ['en', 'fr', 'es'];
                  try {
                    final app = ref.watch(platformApplicationProvider);
                    final themeKey = app.appId.replaceAll('primecare_', '');
                    final palette = ThemeConfig.getAppPalette(themeKey);
                    supportedLanguages = palette.supportedLanguages;
                  } catch (_) {}

                  return supportedLanguages.map((lang) {
                    String title = '';
                    String flag = '';
                    if (lang == 'en') {
                      title = 'English (EN)';
                      flag = '🇺🇸';
                    } else if (lang == 'fr') {
                      title = 'Français (FR)';
                      flag = '🇫🇷';
                    } else if (lang == 'es') {
                      title = 'Español (ES)';
                      flag = '🇪🇸';
                    } else if (lang == 'ar') {
                      title = 'العربية (AR)';
                      flag = '🇸🇦';
                    } else {
                      title = lang.toUpperCase();
                      flag = '🌐';
                    }
                    final isSelected = activeLang == lang;

                    return PrimeCard(
                      elevation: 0,
                      margin: const EdgeInsets.only(bottom: 8),
                      shape: RoundedRectangleBorder(
                        borderRadius: BorderRadius.circular(12),
                        side: BorderSide(
                          color: isSelected ? Theme.of(context).primaryColor : Theme.of(context).colorScheme.outlineVariant,
                          width: isSelected ? 2 : 1,
                        ),
                      ),
                      child: InkWell(
                        onTap: () async {
                          if (context.mounted) {
                            await context.setLocale(Locale(lang));
                          }
                          await ref.read(languageProvider.notifier).setLanguage(lang);

                          // Automatically adjust RTL layout direction for Arabic
                          if (lang == 'ar') {
                            notifier.updateDirection(TextDirection.rtl);
                          } else {
                            notifier.updateDirection(TextDirection.ltr);
                          }
                        },
                        borderRadius: BorderRadius.circular(12),
                        child: Padding(
                          padding: const EdgeInsets.symmetric(horizontal: 16.0, vertical: 12.0),
                          child: Row(
                            children: [
                              PrimeText(flag, style: const TextStyle(fontSize: 20)),
                              const SizedBox(width: 12),
                              Expanded(
                                child: PrimeText(
                                  title,
                                  style: Theme.of(context).textTheme.bodyMedium?.copyWith(
                                        fontWeight: isSelected ? FontWeight.bold : FontWeight.normal,
                                        color: isSelected ? readableThemeForeground(Theme.of(context).colorScheme.surface, Theme.of(context).primaryColor) : null,
                                      ),
                                ),
                              ),
                              if (isSelected)
                                PrimeIcon(
                                  LucideIcons.checkCircle,
                                  color: Theme.of(context).primaryColor,
                                  size: 18,
                                ),
                            ],
                          ),
                        ),
                      ),
                    );
                  });
                }(),
                const SizedBox(height: 24),

                PrimeText(
                  'ADDITIONAL OPTIONS',
                  style: Theme.of(context).textTheme.labelSmall?.copyWith(
                        fontWeight: FontWeight.bold,
                        letterSpacing: 1.2,
                        color: Theme.of(context).colorScheme.onSurfaceVariant,
                      ),
                ),
                const SizedBox(height: 12),

                // Text Direction (RTL / LTR)
                PrimeSwitchListTile(
                  title: const PrimeText('RTL Direction'),
                  subtitle: const PrimeText('Flip elements layout direction'),
                  value: settings.direction == TextDirection.rtl,
                  onChanged: (val) {
                    notifier.updateDirection(
                        val ? TextDirection.rtl : TextDirection.ltr);
                  },
                  secondary: const PrimeIcon(LucideIcons.alignRight),
                ),

                // Custom Scrollbars
                PrimeSwitchListTile(
                  title: const PrimeText('Custom Scrollbars'),
                  subtitle: const PrimeText('Use clean styled scroll bars'),
                  value: settings.customScrollbars,
                  onChanged: (val) {
                    notifier.toggleScrollbars(val);
                  },
                  secondary: const PrimeIcon(LucideIcons.mousePointer),
                ),
              ],
            ),
          ),
          const Divider(),

          // Drawer Footer (Reset)
          Padding(
            padding: const EdgeInsets.all(16.0),
            child: Row(
              children: [
                Expanded(
                  child: PrimeOutlinedButton(
                    style: PrimeOutlinedButton.styleFrom(
                      padding: const EdgeInsets.symmetric(vertical: 16),
                      shape: RoundedRectangleBorder(
                        borderRadius: BorderRadius.circular(12),
                      ),
                    ),
                    onPressed: () {
                      notifier.resetToTenantDefault(tenantDefaultPreset);
                    },
                    child: const PrimeText('Reset to Defaults'),
                  ),
                ),
              ],
            ),
          ),
        ],
      ),
    ),
  );
}

class _LayoutOptionCard extends StatelessWidget {
  final String title;
  final String subtitle;
  final IconData icon;
  final bool isSelected;
  final VoidCallback onTap;

  const _LayoutOptionCard({
    required this.title,
    required this.subtitle,
    required this.icon,
    required this.isSelected,
    required this.onTap,
  });

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);

    return PrimeCard(
      elevation: 0,
      margin: const EdgeInsets.only(bottom: 10),
      shape: RoundedRectangleBorder(
        borderRadius: BorderRadius.circular(12),
        side: BorderSide(
          color: isSelected ? theme.primaryColor : theme.colorScheme.outline,
          width: isSelected ? 2 : 1,
        ),
      ),
      child: InkWell(
        onTap: onTap,
        borderRadius: BorderRadius.circular(12),
        child: Padding(
          padding: const EdgeInsets.all(12.0),
          child: Row(
            children: [
              Container(
                padding: const EdgeInsets.all(8),
                decoration: BoxDecoration(
                  color: isSelected
                      ? theme.primaryColor.withValues(alpha: 0.1)
                      : theme.colorScheme.surfaceContainer,
                  borderRadius: BorderRadius.circular(8),
                ),
                child: PrimeIcon(
                  icon,
                  color: isSelected ? theme.primaryColor : theme.colorScheme.onSurfaceVariant,
                  size: 20,
                ),
              ),
              const SizedBox(width: 16),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    PrimeText(
                      title,
                      style: theme.textTheme.bodyMedium?.copyWith(
                            fontWeight: FontWeight.bold,
                            color: isSelected ? readableThemeForeground(theme.colorScheme.surface, theme.primaryColor) : null,
                          ),
                    ),
                    const SizedBox(height: 2),
                    PrimeText(
                      subtitle,
                      style: theme.textTheme.labelSmall?.copyWith(
                            color: theme.colorScheme.onSurfaceVariant,
                          ),
                    ),
                  ],
                ),
              ),
              if (isSelected)
                PrimeIcon(
                  LucideIcons.checkCircle,
                  color: theme.primaryColor,
                  size: 18,
                ),
            ],
          ),
        ),
      ),
    );
  }
}
